<?php $crud=['table'=>'stock_movements','title'=>'Stock Movement History','singular'=>'Stock Movement','permission'=>'inventory.view','readonly'=>true,'search'=>['movement_type','reference_type','notes'],'list_sql'=>function($qterm=null){ $where='WHERE sm.branch_id=?'; if(trim((string)$qterm)!=='') $where.=' AND (sm.movement_type LIKE ? OR sm.reference_type LIKE ? OR sm.notes LIKE ? OR p.name LIKE ? OR p.brand LIKE ?)'; return 'SELECT sm.*,p.name product,p.brand brand FROM stock_movements sm JOIN products p ON p.id=sm.product_id '.$where.' ORDER BY sm.id DESC LIMIT 500'; },'list_params'=>function($qterm=null){ $params=[current_branch_id()]; if(trim((string)$qterm)!==''){ $like='%'.trim((string)$qterm).'%'; array_push($params,$like,$like,$like,$like,$like); } return $params; },'fields'=>[],'list'=>['created_at'=>'Date','product'=>'Product','movement_type'=>'Type','quantity'=>'Qty Change','balance_after'=>'Balance','reference_type'=>'Reference','notes'=>'Notes']]; require dirname(__DIR__).'/includes/crud.php';